import React from 'react';
import LeftSlidebar from './leftSlidebar';

class EventCreationForm extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      title: "",
      type: "",
      date: "",
      emailFields: [""],
      participants: [{ name: "", iin: "" }],
    };
  }

  handleInputChange = (field, value) => {
    this.setState({ [field]: value });
  };

  handleEmailChange = (index, value) => {
    const newEmailFields = [...this.state.emailFields];
    newEmailFields[index] = value;
    this.setState({ emailFields: newEmailFields });
  };

  addEmailField = () => {
    this.setState(prevState => ({
      emailFields: [...prevState.emailFields, ""]
    }));
  };

  handleParticipantChange = (index, field, value) => {
    const newParticipants = [...this.state.participants];
    newParticipants[index][field] = value;
    this.setState({ participants: newParticipants });
  };

  addParticipant = () => {
    this.setState(prevState => ({
      participants: [...prevState.participants, { name: "", iin: "" }]
    }));
  };

  handleSubmit = () => {
    const { title, type, date, emailFields, participants } = this.state;

    const eventData = {
      title,
      type,
      date,
      emails: emailFields,
      participants,
    };

    fetch('/api/events', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(eventData),
    })
      .then(response => response.json())
      .then(data => {
        alert('Event created successfully!');
        console.log(data);
      })
      .catch(error => {
        console.error('Error:', error);
      });
  };

  render() {
    return (
      <div className="creating-page">
        <header className="main-header"></header>
        <div className="page-main">

          <LeftSlidebar />

          <div className="content">
            <h1>Создание мероприятия</h1>
            <div className="createForm">

              <h3>Название мероприятия</h3>
              <input
                type="text"
                placeholder="Напишите название мероприятия"
                value={this.state.title}
                onChange={(e) => this.handleInputChange("title", e.target.value)}
              />

              <h3>Выберите тип мероприятия</h3>
              <select
                value={this.state.type}
                onChange={(e) => this.handleInputChange("type", e.target.value)}
              >
                <option value="" disabled>Выберите тип мероприятия</option>
                <option value="seminar">Семинар</option>
                <option value="competition">Соревнования</option>
                <option value="conference">Конференция</option>
              </select>

              <h3>Дата проведения</h3>
              <div>
                <input
                  type="datetime-local"
                  className="datetime-input"
                  value={this.state.date}
                  onChange={(e) => this.handleInputChange("date", e.target.value)}
                />
              </div>

              <h3>Добавьте проверяющего(-их)</h3>
              {this.state.emailFields.map((email, index) => (
                <div key={index}>
                  <input
                    type="text"
                    placeholder="Введите почту проверяющего"
                    value={email}
                    onChange={(e) => this.handleEmailChange(index, e.target.value)}
                  />
                </div>
              ))}
              <button type="button" onClick={this.addEmailField}>
                Добавить проверяющего
              </button>

              <h3>Добавьте участника(-ов)</h3>
              {this.state.participants.map((participant, index) => (
                <div key={index}>
                  <h4>Участник №{index + 1}</h4>
                  <input
                    type="text"
                    placeholder="Введите ФИО участника"
                    value={participant.name}
                    onChange={(e) => this.handleParticipantChange(index, "name", e.target.value)}
                  />
                  <input
                    type="number"
                    placeholder="Введите ИИН участника"
                    value={participant.iin}
                    onChange={(e) => this.handleParticipantChange(index, "iin", e.target.value)}
                  />
                </div>
              ))}
              <button type="button" onClick={this.addParticipant}>
                Добавить участника
              </button>

              <button type="button" onClick={this.handleSubmit} className="add-button">
                Создать
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }
}

export default EventCreationForm;
